const views=document.querySelectorAll('.view'),nav=document.querySelectorAll('.nav-link');
nav.forEach(b=>b.addEventListener('click',()=>{nav.forEach(x=>x.classList.remove('active'));b.classList.add('active');views.forEach(x=>x.classList.remove('active-view'));document.getElementById(b.dataset.view).classList.add('active-view');window.scrollTo({top:0,behavior:'smooth'})}));
const store={get(k,f=null){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){localStorage.setItem(k,JSON.stringify(v))}},makeUid=()=>crypto.randomUUID?.()||`cg_${Date.now()}_${Math.random().toString(36).slice(2)}`;
const participantUid=store.get('cg_uid')||makeUid();store.set('cg_uid',participantUid);
const gate=document.getElementById('gate'),termsConsent=document.getElementById('termsConsent'),continueTerms=document.getElementById('continueTerms');
termsConsent.addEventListener('change',()=>continueTerms.disabled=!termsConsent.checked);continueTerms.addEventListener('click',()=>{document.getElementById('termsStep').classList.add('hidden');document.getElementById('profileStep').classList.remove('hidden')});
async function buildDemographics(){const target=document.getElementById('demographicFields'),saved=store.get('cg_profile',{});try{const schema=await fetch('metadata/demographics.schema.json').then(r=>r.json());target.innerHTML=schema.fields.map(f=>`<label>${f.label}<select name="${f.id}" ${f.required?'required':''}>${f.options.map(o=>`<option ${saved[f.id]===o?'selected':''}>${o}</option>`).join('')}</select><span class="field-note">${f.note}</span></label>`).join('')}catch{target.innerHTML='<p>Context fields are unavailable. You can continue without them.</p>'}}buildDemographics();
function enterApp(profile={}){store.set('cg_profile',profile);sessionStorage.setItem('cg_terms_seen','true');gate.classList.add('hidden')}
document.getElementById('profileForm').addEventListener('submit',e=>{e.preventDefault();enterApp(Object.fromEntries(new FormData(e.currentTarget)))});document.getElementById('skipProfile').addEventListener('click',()=>enterApp({}));
const question=document.getElementById('question'),count=document.getElementById('count');question.addEventListener('input',()=>{count.textContent=`${question.value.length} / 500`;count.classList.remove('input-alert')});document.querySelectorAll('.chip:not(.add)').forEach(c=>c.addEventListener('click',()=>c.classList.toggle('selected')));
function cappedTags(containerId,countId){const box=document.getElementById(containerId),label=document.getElementById(countId);if(!box)return()=>[];const buttons=[...box.querySelectorAll('button')],selected=()=>buttons.filter(x=>x.classList.contains('selected')).map(x=>x.dataset.tag);buttons.forEach(b=>b.addEventListener('click',()=>{if(b.classList.contains('selected'))b.classList.remove('selected');else if(selected().length<5)b.classList.add('selected');const n=selected().length;label.textContent=containerId==='filterTags'?`${n} / 5`:`${n} of 5 selected`;buttons.forEach(x=>x.disabled=n>=5&&!x.classList.contains('selected'));if(containerId==='filterTags')filterQuestions()}));return selected}
const getAskTags=cappedTags('askTags','tagCount'),getFilterTags=cappedTags('filterTags','filterCount');
const autoTagRules={Home:/home|house|repair|rent|property/i,Costs:/cost|money|budget|afford|price/i,Community:/community|neighbor|people|local|together/i,Work:/work|job|shift|career/i,Wellbeing:/health|stress|wellbeing|care/i,Education:/school|learn|teach|education/i,Environment:/climate|heat|water|energy|environment/i};
function suggestTags(text){const selected=getAskTags();Object.entries(autoTagRules).forEach(([tag,rule])=>{if(selected.length<5&&rule.test(text)&&!selected.includes(tag)){document.querySelector(`#askTags [data-tag="${tag}"]`)?.click();selected.push(tag)}})}question.addEventListener('blur',()=>suggestTags(question.value));
const piiPattern=/\b[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}\b|\b(?:\+?1[-.\s]?)?(?:\(?\d{3}\)?[-.\s]?)\d{3}[-.\s]?\d{4}\b|\b\d{3}-\d{2}-\d{4}\b/i,unsafePattern=/\b(build a bomb|make a weapon|hurt someone|doxx|steal password|malware|poison)\b/i,dialog=document.getElementById('answerDialog');
document.getElementById('askBtn').addEventListener('click',()=>{const text=question.value.trim();if(!text||!document.getElementById('humanityIntent').checked){count.textContent='Add a question and confirm the humanity-benefit intent.';count.classList.add('input-alert');return}if(piiPattern.test(text)){count.textContent='Possible identifying information detected. Remove it before continuing.';count.classList.add('input-alert');return}if(unsafePattern.test(text)){count.textContent='This request cannot be processed safely.';count.classList.add('input-alert');return}suggestTags(text);const record={id:makeUid(),participant_uid:participantUid,profile:store.get('cg_profile',{}),question:text,tags:getAskTags(),created_at:new Date().toISOString(),prototype_only:true};store.set('cg_questions',[...store.get('cg_questions',[]),record].slice(-25));dialog.dataset.questionId=record.id;document.getElementById('echoQuestion').textContent=text;dialog.showModal()});
document.querySelector('.close').addEventListener('click',()=>dialog.close());
function saveReaction(position,reason=''){store.set('cg_reactions',[...store.get('cg_reactions',[]),{question_id:dialog.dataset.questionId,participant_uid:participantUid,position,reason,created_at:new Date().toISOString()}].slice(-50))}
document.querySelectorAll('[data-rate]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-rate]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');if(b.dataset.rate==='no'){document.getElementById('thanks').classList.add('hidden');document.getElementById('feedback').classList.remove('hidden')}else{document.getElementById('feedback').classList.add('hidden');document.getElementById('thanks').classList.remove('hidden');saveReaction(b.dataset.rate)}}));
document.getElementById('submitFeedback').addEventListener('click',()=>{saveReaction('disagree',document.getElementById('why').value.trim());document.getElementById('feedback').classList.add('hidden');document.getElementById('thanks').classList.remove('hidden')});document.getElementById('followQuestion').addEventListener('click',e=>{e.currentTarget.textContent='✓ Following';store.set('cg_following',true)});document.getElementById('favoriteQuestion').addEventListener('click',e=>{e.currentTarget.textContent='♥ Favorited';store.set('cg_favorite',true)});document.getElementById('askAnother').addEventListener('click',()=>{dialog.close();question.value='';question.focus();count.textContent='0 / 500'});
const search=document.getElementById('searchQuestions');function filterQuestions(){const query=(search?.value||'').toLowerCase().trim(),tags=getFilterTags();let visible=0;document.querySelectorAll('#questionList article').forEach(card=>{const cardTags=card.dataset.tags.split(','),show=(!query||card.dataset.title.includes(query))&&(!tags.length||tags.every(tag=>cardTags.includes(tag)));card.classList.toggle('hidden',!show);if(show)visible++});document.getElementById('resultCount').textContent=`${visible} question${visible===1?'':'s'}`;document.getElementById('emptyState').classList.toggle('hidden',visible!==0)}search?.addEventListener('input',filterQuestions);document.getElementById('clearSearch')?.addEventListener('click',()=>{search.value='';document.querySelectorAll('#filterTags button.selected').forEach(x=>x.click());filterQuestions()});document.querySelectorAll('.leaf,.seed').forEach(n=>n.addEventListener('click',()=>document.getElementById('treeNote').textContent=`${n.textContent} — ${n.dataset.note}`));
